#!/usr/bin/env python3
"""Build the reviewed skill-disposition ledger for Wayfinder issue 29."""

from __future__ import annotations

import argparse
import collections
import json
from pathlib import Path


EXPECTED_SUMMARY = {
    "migrate": 2,
    "consolidate": 5,
    "archive": 50,
    "retain in place": 127,
    "discard": 730,
    "total": 914,
}


def classify(path: str, name: str) -> tuple[str, str, str, list[str]]:
    normalized = path.replace("\\", "/")

    if normalized.startswith("/home/saabendtsen/.hermes/"):
        return (
            "discard",
            "hermes_not_retained",
            "no independent skill authority",
            ["credential_containment", "complete_retirement_inventory"],
        )
    if normalized == "C:/Users/Quiet/.codex/skills":
        return (
            "consolidate",
            "broad_skill_root",
            "specifically classified installed skill packages",
            ["residual_content_and_provenance_check"],
        )
    if normalized == "C:/Users/Quiet/.codex/skills/.system":
        return (
            "retain in place",
            "managed_system_skill",
            "Codex-managed system skill installation",
            ["reinstallation_source_record"],
        )
    if normalized.startswith("C:/Users/Quiet/.codex/skills/"):
        if name in {"server-codex-task", "wayfinder-autopilot"}:
            return (
                "consolidate",
                "installed_copy_with_git_authority",
                f"workspace control repository skills/{name}",
                ["content_diff_and_adapter_verification"],
            )
        return (
            "retain in place",
            "upstream_managed_skill_installation",
            "reviewed upstream skill source and installed Codex discovery view",
            ["upstream_revision_and_reinstallation_record"],
        )
    if normalized == "C:/Users/Quiet/.agents/skills":
        return (
            "migrate",
            "local_only_skill_root",
            "scoped canonical Git skill source",
            ["content_inventory", "scope_and_authority_review"],
        )
    if normalized == "C:/Dev/homelab/skills":
        return (
            "consolidate",
            "broad_skill_root",
            "workspace control repository skill packages",
            ["residual_content_and_provenance_check"],
        )
    if normalized.startswith("C:/Dev/homelab/skills/"):
        return (
            "retain in place",
            "canonical_git_skill_source",
            "workspace control repository",
            [],
        )
    if normalized.startswith(("C:/Dev/homelab-task-14/", "C:/Dev/homelab-wayfinder-global/")):
        return (
            "archive",
            "historical_worktree_skill",
            "protected historical workspace-worktree archive",
            ["content_reconciliation_before_later_discard"],
        )
    if normalized.startswith(
        "C:/Users/Quiet/OneDrive - Tech-Logic ApS/Dokumenter/Repos/home-server/"
    ):
        return (
            "archive",
            "historical_server_copy_skill",
            "protected historical home-server recovery archive",
            ["content_reconciliation_before_later_discard"],
        )
    if normalized.startswith("C:/Users/Quiet/.codex/plugins/cache/"):
        return (
            "retain in place",
            "active_managed_plugin_installation",
            "Codex plugin manager and recorded package source",
            ["package_version_and_reinstallation_record"],
        )
    if normalized.startswith(
        (
            "C:/Users/Quiet/.codex/.tmp/",
            "C:/Users/Quiet/.codex/.tmp",
        )
    ):
        return (
            "discard",
            "reproducible_temporary_skill_artifact",
            "package or marketplace source",
            ["reinstallation_evidence_before_cleanup"],
        )
    if normalized.startswith("C:/Users/Quiet/.claude/plugins/marketplaces/"):
        return (
            "retain in place",
            "active_managed_marketplace_installation",
            "Claude marketplace manager and recorded upstream source",
            ["package_version_and_reinstallation_record"],
        )
    if normalized.startswith("/home/saabendtsen/.codex/.tmp/"):
        return (
            "discard",
            "reproducible_temporary_skill_artifact",
            "package or marketplace source",
            ["reinstallation_evidence_before_cleanup"],
        )
    if normalized.startswith("/home/saabendtsen/.codex/plugins/cache/"):
        return (
            "discard",
            "superseded_server_plugin_cache",
            "recorded package source",
            ["package_version_and_reinstallation_evidence_before_cleanup"],
        )
    if normalized.startswith("/home/saabendtsen/.codex/skills"):
        return (
            "discard",
            "superseded_managed_system_skill",
            "Codex distribution source",
            ["reinstallation_evidence_before_cleanup"],
        )
    if normalized.startswith(
        (
            "/home/saabendtsen/.claude/plugins/marketplaces/",
            "/home/saabendtsen/.claude/plugins/cache/",
        )
    ):
        return (
            "discard",
            "superseded_server_plugin_artifact",
            "recorded marketplace or package source",
            ["package_version_and_reinstallation_evidence_before_cleanup"],
        )
    if normalized == "/home/saabendtsen/.claude/skills":
        return (
            "migrate",
            "server_only_skill_root",
            "scoped canonical Git skill source",
            ["content_inventory", "sensitivity_and_scope_review"],
        )
    if normalized == "/home/saabendtsen/projects/samtalen/.codex/skills":
        return (
            "consolidate",
            "project_scoped_skill_root",
            "Samtalen application repository",
            ["repository_reconciliation", "residual_content_check"],
        )
    if normalized.startswith(
        (
            "/home/saabendtsen/.vscode-server/",
            "/home/saabendtsen/actions-runner/",
        )
    ):
        return (
            "discard",
            "misclassified_packaged_tool_artifact",
            "owning package or tool distribution",
            ["reinstallation_evidence_before_cleanup"],
        )
    raise ValueError(f"unclassified skill migration unit: {path}")


def build(registry: dict) -> dict:
    units = [unit for unit in registry["migration_units"] if unit["kind"] == "skill"]
    decisions = []
    for unit in units:
        if len(unit["locations"]) != 1:
            raise ValueError(f"expected one location for {unit['id']}")
        location = unit["locations"][0]
        disposition, basis, target, follow_up = classify(location["path"], unit["name"])
        decisions.append(
            {
                "id": unit["id"],
                "name": unit["name"],
                "categories": unit["categories"],
                "location": location,
                "disposition": disposition,
                "basis": basis,
                "target_authority": target,
                "required_follow_up": follow_up,
                "reconciliation_status": unit["reconciliation_status"],
                "sensitivity": unit["sensitivity"],
            }
        )

    counts = collections.Counter(decision["disposition"] for decision in decisions)
    summary = {key: counts[key] for key in EXPECTED_SUMMARY if key != "total"}
    summary["total"] = len(decisions)
    if summary != EXPECTED_SUMMARY:
        raise ValueError(f"unexpected disposition summary: {summary}")

    return {
        "schema_version": "1.0",
        "decided_at": "2026-08-13",
        "decision_ticket": "https://github.com/saabendtsen/homelab-workspace/issues/29",
        "source_registry": "inventories/migration-unit-registry-2026-08-08.json",
        "summary": summary,
        "controls": [
            "A skill migration unit is a physical inventory observation and may be a real skill package, a broad directory envelope, or material misclassified because its path contains a skills segment.",
            "A first-party Git-tracked skill source outranks installed copies; package and marketplace sources outrank reproducible caches and temporary catalogs.",
            "Current upstream-managed workstation installations remain in place while their source revision and reinstall path are recorded.",
            "Project-scoped skills consolidate only into their application repository; workspace-scoped skills consolidate only into the workspace control repository or another explicitly reviewed scoped authority.",
            "Historical worktree and OneDrive copies remain protected archives until content reconciliation proves they have no unique material.",
            "All Hermes skill observations are discarded as independent migration units by explicit user decision; no Hermes content is selected for migration, consolidation, or archive.",
            "Discard means no independent migration-unit preservation is required; it does not authorize deleting an underlying file, directory, package, repository, service, configuration, session, job, or data collection.",
            "No deletion, movement, publication, service change, credential change, sync change, or protected-value exposure is authorized by this ledger.",
            "Hermes credential containment and full retirement require separately inventoried execution work and explicit destructive-target confirmation.",
        ],
        "decision_bases": {
            "active_managed_marketplace_installation": "An active workstation marketplace installation remains at its package-manager-owned runtime location.",
            "active_managed_plugin_installation": "An active workstation plugin installation remains at its package-manager-owned runtime location.",
            "broad_skill_root": "A directory envelope consolidates into its specifically classified child authorities after residual-content review.",
            "canonical_git_skill_source": "The Git-tracked workspace skill package is already at its canonical authority.",
            "hermes_not_retained": "The user explicitly rejected preservation of all Hermes material after evidence showed unreliable operation and predominantly upstream, generated, or duplicate content.",
            "historical_server_copy_skill": "A historical OneDrive server copy remains recovery evidence until content reconciliation is complete.",
            "historical_worktree_skill": "An obsolete workspace worktree remains recovery evidence until content reconciliation is complete.",
            "installed_copy_with_git_authority": "An installed skill copy consolidates into its Git-tracked workspace authority after content comparison.",
            "local_only_skill_root": "A workstation-only skill root requires migration into a reviewed scoped Git authority.",
            "managed_system_skill": "A distribution-managed workstation system skill remains installed and reproducible from its owning distribution.",
            "misclassified_packaged_tool_artifact": "A package-owned docs, tests, or runtime directory named skills has no independent skill authority.",
            "project_scoped_skill_root": "A project-specific skill collection belongs in the owning application repository.",
            "reproducible_temporary_skill_artifact": "A temporary catalog or package checkout is reproducible from its recorded source.",
            "server_only_skill_root": "A server-only authored skill root requires reviewed migration before server-first behavior is retired.",
            "superseded_managed_system_skill": "A server-side distribution-managed system skill has no independent preservation value in the workstation-first estate.",
            "superseded_server_plugin_artifact": "A server-side marketplace or plugin artifact is reproducible and superseded by workstation-first operation.",
            "superseded_server_plugin_cache": "A server-side plugin cache is reproducible and superseded by workstation-first operation.",
            "upstream_managed_skill_installation": "An installed upstream skill remains a runtime discovery view governed by its reviewed upstream source.",
        },
        "decisions": decisions,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--registry", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    registry = json.loads(args.registry.read_text(encoding="utf-8"))
    ledger = build(registry)
    args.output.write_text(json.dumps(ledger, indent=2) + "\n", encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

