    units = [unit for unit in registry["migration_units"] if unit["kind"] == "skill"]
    decisions = []
    for unit in units:
        if len(unit["locations"]) != 1:
            raise ValueError(f"expected one location for {unit['id']}")
        location = unit["locations"][0]
        disposition, basis, target, follow_up = classify(location["path"], unit["name"])
        decisions.append(
            {
                "id": unit["id"],
                "name": unit["name"],
                "categories": unit["categories"],
                "location": location,
                "disposition": disposition,
                "basis": basis,
