                "required_follow_up": follow_up,
                "reconciliation_status": unit["reconciliation_status"],
                "sensitivity": unit["sensitivity"],
            }
        )

    counts = collections.Counter(decision["disposition"] for decision in decisions)
    summary = {key: counts[key] for key in EXPECTED_SUMMARY if key != "total"}
    summary["total"] = len(decisions)
    if summary != EXPECTED_SUMMARY:
