            "Current upstream-managed workstation installations remain in place while their source revision and reinstall path are recorded.",
            "Project-scoped skills consolidate only into their application repository; workspace-scoped skills consolidate only into the workspace control repository or another explicitly reviewed scoped authority.",
            "Historical worktree and OneDrive copies remain protected archives until content reconciliation proves they have no unique material.",
            "All Hermes skill observations are discarded as independent migration units by explicit user decision; no Hermes content is selected for migration, consolidation, or archive.",
            "Discard means no independent migration-unit preservation is required; it does not authorize deleting an underlying file, directory, package, repository, service, configuration, session, job, or data collection.",
            "No deletion, movement, publication, service change, credential change, sync change, or protected-value exposure is authorized by this ledger.",
            "Hermes credential containment and full retirement require separately inventoried execution work and explicit destructive-target confirmation.",
        ],
        "decision_bases": {
            "active_managed_marketplace_installation": "An active workstation marketplace installation remains at its package-manager-owned runtime location.",
            "active_managed_plugin_installation": "An active workstation plugin installation remains at its package-manager-owned runtime location.",
            "broad_skill_root": "A directory envelope consolidates into its specifically classified child authorities after residual-content review.",
            "canonical_git_skill_source": "The Git-tracked workspace skill package is already at its canonical authority.",
            "hermes_not_retained": "The user explicitly rejected preservation of all Hermes material after evidence showed unreliable operation and predominantly upstream, generated, or duplicate content.",
            "historical_server_copy_skill": "A historical OneDrive server copy remains recovery evidence until content reconciliation is complete.",
            "historical_worktree_skill": "An obsolete workspace worktree remains recovery evidence until content reconciliation is complete.",
            "installed_copy_with_git_authority": "An installed skill copy consolidates into its Git-tracked workspace authority after content comparison.",
            "local_only_skill_root": "A workstation-only skill root requires migration into a reviewed scoped Git authority.",
            "managed_system_skill": "A distribution-managed workstation system skill remains installed and reproducible from its owning distribution.",
            "misclassified_packaged_tool_artifact": "A package-owned docs, tests, or runtime directory named skills has no independent skill authority.",
            "project_scoped_skill_root": "A project-specific skill collection belongs in the owning application repository.",
            "reproducible_temporary_skill_artifact": "A temporary catalog or package checkout is reproducible from its recorded source.",
            "server_only_skill_root": "A server-only authored skill root requires reviewed migration before server-first behavior is retired.",
            "superseded_managed_system_skill": "A server-side distribution-managed system skill has no independent preservation value in the workstation-first estate.",
            "superseded_server_plugin_artifact": "A server-side marketplace or plugin artifact is reproducible and superseded by workstation-first operation.",
            "superseded_server_plugin_cache": "A server-side plugin cache is reproducible and superseded by workstation-first operation.",
            "upstream_managed_skill_installation": "An installed upstream skill remains a runtime discovery view governed by its reviewed upstream source.",
        },
        "decisions": decisions,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--registry", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    registry = json.loads(args.registry.read_text(encoding="utf-8"))
    ledger = build(registry)
    args.output.write_text(json.dumps(ledger, indent=2) + "\n", encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

